    `sort` and `direction` are the ?sort= and ?dir= values of the request. The header links
    of the table use the SORTABLE columns with "asc" or "desc".
    """
    limit = max(1, min(int(limit), MAX_PAGE))
    if sort not in SORTABLE:
        sort = "issued_on"
    if direction not in ("asc", "desc"):
        direction = "asc"
    cur = conn.execute(
        "SELECT number, amount_cents, issued_on FROM invoices WHERE customer_id = ? ORDER BY {sort} {direction} LIMIT ?",
        (customer_id, limit, sort, direction),
    )
    return cur.fetchall()

